scripts.text:
-- 1. Create and switch to Database context
IF NOT EXISTS (SELECT * FROM sys.databases WHERE name = 'advw')
BEGIN
    CREATE DATABASE [advw];
END;


USE [advw];


-- 2. Create Master Key if it does not exist
IF NOT EXISTS (SELECT * FROM sys.symmetric_keys WHERE name = '##MS_DatabaseMasterKey##')
BEGIN
    CREATE MASTER KEY ENCRYPTION BY PASSWORD = 'rafiul735150@#';
END;


-- 3. Create Database Scoped Credential if it does not exist
IF NOT EXISTS (SELECT * FROM sys.database_scoped_credentials WHERE name = 'advwrk')
BEGIN
    CREATE DATABASE SCOPED CREDENTIAL advwrk
    WITH IDENTITY = 'Managed Identity';
END;


-- 4. Create External Data Sources
IF NOT EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'SilverData')
BEGIN
    CREATE EXTERNAL DATA SOURCE SilverData
    WITH (
        LOCATION = 'https://advwprojectstorage.blob.core.windows.net/silver',
        CREDENTIAL = advwrk
    );
END;


IF NOT EXISTS (SELECT * FROM sys.external_data_sources WHERE name = 'GoldData')
BEGIN
    CREATE EXTERNAL DATA SOURCE GoldData
    WITH (
        LOCATION = 'https://advwprojectstorage.blob.core.windows.net/gold',
        CREDENTIAL = advwrk
    );
END;


-- 5. Create Schema named 'ld' inside the database
IF NOT EXISTS (SELECT * FROM sys.schemas WHERE name = 'gold')
BEGIN
    EXEC('CREATE SCHEMA [gold]');
END;


-- 6. Create Parquet External File Format inside 'gold' schema
IF NOT EXISTS (SELECT * FROM sys.external_file_formats WHERE name = 'parquet_format')
BEGIN
    CREATE EXTERNAL FILE FORMAT [parquet_format]
    WITH (
        FORMAT_TYPE = PARQUET,
        DATA_COMPRESSION = 'org.apache.hadoop.io.compress.SnappyCodec'
    );
END;
